-- ============================================================================
-- MIG331 · Las mediciones reales de junio 2026 entran a producción
-- ----------------------------------------------------------------------------
-- Nueve días de cierre físico de Romeral — varillas, numerales de cuentalitros
-- y recepciones — tomados del respaldo de la aplicación con que hoy se trabaja
-- (Mediciones_1.json). No son datos de prueba: son las mediciones que el
-- encargado de estación tomó en terreno del 1 al 9 de junio.
--
-- POR QUÉ ENTRAN
-- Un sistema de control de inventario sin historia no controla nada: la
-- variación de un día sola es ruido, y el criterio del instructivo — la
-- variación acumulada del mes — necesita una serie. Estos nueve días son la
-- línea base contra la que se van a leer los días que vienen.
--
-- Se cargan como cierres FIRMADOS porque ya ocurrieron y ya se informaron.
-- El RPC los inserta con ON CONFLICT, así que repetir la migración no
-- duplica: reescribe los mismos días con los mismos números.
-- ============================================================================
BEGIN;
SELECT set_config('request.jwt.claims', json_build_object('sub',(SELECT u.id::text FROM usuarios_perfil u WHERE u.rol='supervisor' AND u.activo LIMIT 1),'role','authenticated')::text, true);
DO $rep$
